"""Roteiros dos vídeos longos 06 a 11 (formato 2: imagens, prática, inscrição e compromisso).
python3 roteiros_06_11.py  ->  grava longos/NN/roteiro.json"""
import json, os
B = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'longos')

def A(h, s, txt, img='maquiavel.jpg'): return {'tela': {'t': 'abertura', 'h': h, 's': s, 'img': img}, 'txt': txt}
def F(h, txt): return {'tela': {'t': 'frase', 'h': h}, 'txt': txt}
def C(n, h, s, txt): return {'tela': {'t': 'capitulo', 'n': n, 'h': h, 's': s}, 'txt': txt}
def Q(h, s, txt): return {'tela': {'t': 'citacao', 'h': h, 's': s}, 'txt': txt}
def I(img, h, s, txt): return {'tela': {'t': 'imagem', 'img': img, 'h': h, 's': s}, 'txt': txt}
def D(a, as_, b, bs, txt): return {'tela': {'t': 'duo', 'a': a, 'as': as_, 'b': b, 'bs': bs}, 'txt': txt}
def P(itens, txt, h='Na prática'): return {'tela': {'t': 'pratica', 'h': h, 'itens': itens}, 'txt': txt}
def SUB(txt): return {'tela': {'t': 'inscreva'}, 'txt': txt}
def COM(h, txt): return {'tela': {'t': 'compromisso', 'h': h}, 'txt': txt}
def RES(itens, txt): return {'tela': {'t': 'resumo', 'h': 'Resumo', 'itens': itens}, 'txt': txt}
def FIM(txt): return {'tela': {'t': 'fim'}, 'txt': txt}

